PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS entities(id TEXT PRIMARY KEY,kind TEXT NOT NULL,org TEXT NOT NULL,branch TEXT NOT NULL DEFAULT '',data TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS entities_scope ON entities(org,kind,branch);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL,org TEXT NOT NULL,branch TEXT NOT NULL DEFAULT '',hash TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pairs(hash TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,expires INTEGER NOT NULL,device TEXT);
CREATE TABLE IF NOT EXISTS device_keys(hash TEXT PRIMARY KEY,device TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,org TEXT NOT NULL,branch TEXT NOT NULL,user TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS audit_scope ON audit(org,at);
CREATE TABLE IF NOT EXISTS plays(batch TEXT PRIMARY KEY,org TEXT NOT NULL,branch TEXT NOT NULL,device TEXT NOT NULL,media TEXT NOT NULL,day TEXT NOT NULL,count INTEGER NOT NULL,seconds REAL NOT NULL,last INTEGER NOT NULL,received INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS daily(org TEXT NOT NULL,branch TEXT NOT NULL,device TEXT NOT NULL,media TEXT NOT NULL,day TEXT NOT NULL,count INTEGER NOT NULL,seconds REAL NOT NULL,last INTEGER NOT NULL,PRIMARY KEY(device,media,day));
CREATE INDEX IF NOT EXISTS daily_scope ON daily(org,day);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,org TEXT NOT NULL,branch TEXT NOT NULL,device TEXT NOT NULL,health TEXT NOT NULL,message TEXT NOT NULL,at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_scope ON events(org,at);
